export function buildSpecialistHTML(engineSource,modelData,projectName,threshold=.64){
  const state={threshold};
  const engine=engineSource.replace(/export /g,'');
    const model=JSON.stringify(modelData).replace(/</g,'\\u003c');
    const name=JSON.stringify(projectName).replace(/</g,'\\u003c');
  return `<!doctype html><html lang="sv"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Min Signal-specialist</title><style>body{margin:0;background:#f5f6f2;color:#1b2028;font:16px system-ui}main{max-width:760px;margin:7vh auto;padding:24px}h1{font-size:42px;letter-spacing:-2px}p{line-height:1.7;color:#59665e}.card{background:white;border:1px solid #dfe5d8;padding:25px;border-radius:20px;margin:20px 0}textarea{box-sizing:border-box;width:100%;font:inherit;padding:16px;border:1px solid #ccd5c3;border-radius:12px;min-height:150px}button{background:#d1fa87;color:#23351b;border:0;border-radius:10px;padding:13px 20px;font:inherit;cursor:pointer;margin-top:14px}.row{display:flex;justify-content:space-between;gap:15px;padding:12px 0;border-bottom:1px solid #e6ebdf}.tag{background:#edf2e6;padding:5px 10px;border-radius:15px;font-size:12px}.warning{color:#91632b}.brand{font-size:12px;letter-spacing:2px}h2{font-size:30px;letter-spacing:-1px}label{display:block;margin-bottom:12px;font-size:13px}</style><main><span class="brand">MPAI SIGNAL / DIN EGEN SPECIALIST</span><h1 id="name"></h1><p>Tränad av dig. Körs lokalt på den här enheten, även utan nätverk. Ingen text skickas iväg.</p><section class="card"><label for="text">Text att sortera</label><textarea id="text" maxlength="12000" placeholder="Skriv eller klistra in en text…"></textarea><button id="run">Visa modellens förslag ↗</button><div id="result" aria-live="polite"></div></section><p>Modellen väljer en kategori per text utifrån statistiska ordmönster. Modellpoäng är inte en verifierad sannolikhet att svaret är rätt. Granska viktiga beslut. Originalexemplen finns inte i filen, men modellvikter kan innehålla inlärda uppgifter.</p><p id="categories"></p><p>Skapad med MPAI Signal. Ändra eller träna om modellen genom att importera din modellfil i Signal.</p></main><script>${engine}\nconst model=${model};document.getElementById('name').textContent=${name};document.getElementById('categories').textContent='Kategorier: '+model.labels.join(' · ');document.getElementById('run').onclick=()=>{const t=document.getElementById('text').value,r=document.getElementById('result');r.replaceChildren();if(!t.trim())return;const p=predict(model,t,${state.threshold});const badge=document.createElement('p');badge.className=p.review?'warning':'';badge.textContent=p.review?'Behöver granskas: '+p.reasons.join(' · '):'Modellens förslag';r.append(badge);const h=document.createElement('h2');h.textContent=p.label;r.append(h);for(const v of p.ranking){const row=document.createElement('div');row.className='row';const a=document.createElement('span'),b=document.createElement('span');a.textContent=v.label;b.textContent=Math.round(v.score*100)+'% modellpoäng';row.append(a,b);r.append(row);}};<\/script></html>`;
}
